<?php
require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require __DIR__.'/../app/online_fulfillment.php'; require_permission('manage_online_orders');
$err='';$msg='';
function scoped_order_sql(): array {if(is_super_admin())return ['',[]];$ids=assigned_location_ids();if(!$ids)return [' AND 1=0',[]];$ph=implode(',',array_fill(0,count($ids),'?'));return [" AND EXISTS(SELECT 1 FROM online_order_allocations ax WHERE ax.online_order_id=o.id) AND NOT EXISTS(SELECT 1 FROM online_order_allocations ay WHERE ay.online_order_id=o.id AND ay.location_id NOT IN ($ph))",$ids];}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';try{if(!$id||!can_access_online_order($id))throw new Exception('Order is outside your location scope.');db()->beginTransaction();$st=db()->prepare('SELECT * FROM online_orders WHERE id=? FOR UPDATE');$st->execute([$id]);$o=$st->fetch();if(!$o)throw new Exception('Order not found.');
 if($action==='reset_pick') {if(!in_array($o['status'],['PICKING','PICKED','PACKING','PACKED'],true))throw new Exception('This order does not need a pick reset.');if(empty($_POST['physical_return_confirm']))throw new Exception('Confirm that all picked/packed pieces were physically returned to their original rack/bin.');db()->prepare("UPDATE online_order_allocations SET picked_qty=0,packed_qty=0,status='RESERVED',picked_by=NULL,packed_by=NULL,picked_at=NULL,packed_at=NULL WHERE online_order_id=? AND status IN ('RESERVED','PICKED','PACKED')")->execute([$id]);db()->prepare("UPDATE online_orders SET status='ALLOCATED',packed_by=NULL,packed_at=NULL WHERE id=?")->execute([$id]);$msg='Pick/pack reset. Items remain reserved and must be back in original bins.';}
 elseif($action==='cancel'){if(in_array($o['status'],['DISPATCHED','DELIVERED','RETURN_IN_TRANSIT','RETURNED'],true))throw new Exception('Post-dispatch order cannot be cancelled here. Use Delivery/RTO workflow.');$t=online_order_totals($id);if((float)$t['picked']>0||(float)$t['packed']>0)throw new Exception('Reset Pick/Pack and physically return items to bins before cancellation.');online_release_reservations($id);db()->prepare("UPDATE online_orders SET status='CANCELLED',updated_at=NOW() WHERE id=?")->execute([$id]);$msg='Order cancelled and reserved stock released.';}
 else throw new Exception('Invalid action.');db()->commit();audit('ONLINE_ORDER_'.strtoupper($action),'online_order',$id);publish_event('ONLINE_ORDER_STATUS','Online order updated',online_order_number($id).' · '.$msg,['super_admin'],'online_order',$id,null);publish_scoped_event('ONLINE_ORDER_STATUS','Online order updated',online_order_number($id).' · '.$msg,['manager','godown'],'online_order',$id);
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
[$scope,$params]=scoped_order_sql();$status=trim($_GET['status']??'');$sql="SELECT o.*,COALESCE(SUM(a.quantity),0) allocated,COALESCE(SUM(a.picked_qty),0) picked,COALESCE(SUM(a.packed_qty),0) packed FROM online_orders o LEFT JOIN online_order_allocations a ON a.online_order_id=o.id AND a.status<>'RELEASED' WHERE 1=1".$scope;$args=$params;if($status!==''){$sql.=' AND o.status=?';$args[]=$status;}$sql.=' GROUP BY o.id ORDER BY o.id DESC LIMIT 1000';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$orderItems=[];if($rows){$ids=array_map('intval',array_column($rows,'id'));$ist=db()->prepare("SELECT oi.online_order_id oid,p.sku,p.product_name,p.color,p.size,SUM(oi.quantity) qty,(SELECT GROUP_CONCAT(DISTINCT l.code ORDER BY l.code SEPARATOR ', ') FROM online_order_allocations a JOIN locations l ON l.id=a.location_id WHERE a.online_order_id=oi.online_order_id AND a.product_id=oi.product_id AND a.status<>'RELEASED') locs FROM online_order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.online_order_id IN (".implode(',',array_fill(0,count($ids),'?')).") GROUP BY oi.online_order_id,oi.product_id,p.sku,p.product_name,p.color,p.size ORDER BY p.sku");$ist->execute($ids);foreach($ist->fetchAll() as $it)$orderItems[(int)$it['oid']][]=$it;}page_header('Online Orders / Fulfilment Control');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<div class="actions no-print"><a class="btn" href="online_order_new.php">+ New Online Order</a><form method="get"><select name="status"><option value="">All Status</option><?php foreach(['ALLOCATED','PICKING','PICKED','PACKING','PACKED','DISPATCHED','DELIVERED','RETURN_IN_TRANSIT','RETURNED','CANCELLED'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn secondary">Filter</button></form></div><br>
<table><tr><th>Order</th><th>Source</th><th>Customer</th><th>Items · Rack/Bin</th><th>Amount</th><th>Progress</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['order_no'])?></b><div class="muted"><?=e($r['external_order_id'])?> · <?=e($r['created_at'])?></div></td><td><?=e($r['source'])?></td><td><?=e($r['customer_name'])?><div class="muted"><?=e($r['customer_mobile'])?></div></td><td><?php foreach($orderItems[(int)$r['id']]??[] as $it):?><div><b><?=e($it['sku'])?></b> × <?=e((float)$it['qty'])?> <a href="scan_find.php?code=<?=e(urlencode($it['sku']))?>" title="Find in godown">Find</a><div class="muted"><?=e(trim($it['product_name'].' · '.$it['color'].' / '.$it['size'],' ·/'))?><?php if($it['locs']):?> · <?=e($it['locs'])?><?php endif;?></div></div><?php endforeach;?></td><td>₹<?=e(number_format((float)$r['order_amount'],2))?><div class="muted"><?=e($r['payment_status'])?></div></td><td><?=e($r['picked'])?> / <?=e($r['allocated'])?> picked<br><?=e($r['packed'])?> / <?=e($r['allocated'])?> packed</td><td><span class="badge"><?=e($r['status'])?></span><?php if($r['awb']):?><div class="muted"><?=e($r['courier'].' · '.$r['awb'])?></div><?php endif;?></td><td class="actions"><?php if(in_array($r['status'],['ALLOCATED','PICKING'],true)):?><a class="btn secondary" href="online_pick.php?id=<?=$r['id']?>">Pick</a><?php endif;?><?php if(in_array($r['status'],['PICKED','PACKING'],true)):?><a class="btn secondary" href="online_pack.php?id=<?=$r['id']?>">Pack</a><?php endif;?><?php if(in_array($r['status'],['PACKED','DISPATCHED','DELIVERED'],true)&&has_permission('fulfill_online_orders')):?><a class="btn secondary" target="_blank" href="online_pack.php?id=<?=$r['id']?>&amp;slip=1">Packing Slip</a><?php endif;?><?php if($r['status']==='PACKED'&&has_permission('dispatch_online_orders')):?><a class="btn secondary" href="online_dispatch.php?id=<?=$r['id']?>">Dispatch</a><?php endif;?><?php if(in_array($r['status'],['PICKING','PICKED','PACKING','PACKED'],true)):?><form method="post" onsubmit="return confirm('Only continue after all items are physically returned to original rack/bin.');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="reset_pick"><input type="hidden" name="physical_return_confirm" value="1"><button class="btn secondary">Reset Pick</button></form><?php endif;?><?php if(!in_array($r['status'],['DISPATCHED','DELIVERED','RETURN_IN_TRANSIT','RETURNED','CANCELLED'],true)):?><form method="post" onsubmit="return confirm('Cancel order and release reserved stock?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="cancel"><button class="btn danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></table>
<div class="notice"><b>Important:</b> Cancel is allowed only after picked quantities are reset to zero. This prevents software stock from saying “rack available” while the physical garment is still at the packing table.</div><?php page_footer();
